import{_ as l,l as t,o as a,c,v as i,p,x as e,d as s,i as n,S as d}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"blkio cgroup","description":"","frontmatter":{"title":"blkio cgroup","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/blkio-cgroup.md","filePath":"cs/blkio-cgroup.md","lastUpdated":1789023840000}'),u={name:"cs/blkio-cgroup.md"};function b(h,o,g,k,_,m){const r=t("Mermaid");return a(),c("div",null,[o[1]||(o[1]=i('<h1 id="blkio-cgroup" tabindex="-1">blkio cgroup <a class="header-anchor" href="#blkio-cgroup" aria-label="Permalink to &quot;blkio cgroup&quot;">​</a></h1><div class="epigraph"><p>blkio（io 控制器）给 cgroup 挂上每设备的权重、bps、iops 上限，使容器不能把共享盘打满。</p><footer>—— 据 Linux cgroup v2 io 文档；内核 blk-cgroup 说明</footer></div><p><a href="/cs/io-polling">上一课</a>把设备用到满带宽。<a href="/cs/cgroups">cgroups</a> 主干有组；<a href="/cs/blk-schedulers">BFQ</a> 能看权重。缺口是 <strong>io 控制器</strong>：统计与限制如何接到 bio，以及 v1 blkio 与 v2 io 的差别点到为止。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多租户共享一块 NVMe，一个容器 <code>dd</code> 会抬高所有人的延迟。io.max：bps/iops 上限；io.weight：在支持的调度器上相对份额。缺口：限制发生在 blk-cgroup 节流，可能睡眠提交者；递归统计；缓冲 I/O 的归属按谁脏页——异步写回可能记到根组，这是著名坑。本课不把 cpu 控制器再讲一遍。</p><p><span class="marginnote">writeback 归属（cgroup writeback）要把 inode 与 memcg/io 关联，否则限制被绕过。教学上承认「脏页回写的会计」是机制一部分。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>提交 bio 时：查任务的 css，若超过 iops 则 <code>blk_throtl</code> 延迟。完成时加统计。对照 <a href="/cs/fs-quota">配额</a>：配额是 FS 持久占用；blkio 是即时带宽。对照 <a href="/cs/thin-provisioning">thin</a>：池满是容量，不是 iops。对照 NVMe：限制在软件，设备仍看见合并后的请求。</p>',8)),(a(),p(d,null,{default:e(()=>[n(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIO%5B%22bio%22%5D%20--%3E%20CG%5B%22blk-cgroup%22%5D%0A%20%20CG%20--%3E%7C%22%E8%B6%85%E9%99%90%22%7C%20THR%5B%22%E8%8A%82%E6%B5%81%E7%9D%A1%E7%9C%A0%22%5D%0A%20%20CG%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20Q%5B%22%E5%9D%97%E9%98%9F%E5%88%97%22%5D%0A%20%20WB%5B%22writeback%22%5D%20--%3E%20OWN%5B%22%E6%8C%89%20inode%20%E5%BD%92%E5%B1%9E%E7%BB%84%22%5D%0A"})]),fallback:e(()=>[...o[0]||(o[0]=[s(" Loading... ",-1)])]),_:1})),o[2]||(o[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>blkio 把设备当成可计量的共享资源，使「容器隔离」在 I/O 维可执行。它不加密、不冗余。不要写成云产品 QoS 页面。与轮询：被节流的线程 poll 也会空转，策略要一起设计。</p><p>v2 统一 io 控制器；旧 blkio 文件名不同，对象相同。</p><p>实现上：异步回写若记到 root，容器上限等于没设。cgroup writeback 用 inode 归属把脏页会计拉回组。iops 限制对 NVMe 很有效，对 HDD 可能只是把队列变短。 读法上只引用<a href="/cs/io-polling">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>blkio cgroup</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 <code>io.latency</code>/<code>io.cost</code> 模型细节。不保证网络块设备（iSCSI）上的统计准到应用级。下一课请求里的「必须到介质」标志：写屏障与 FUA。</p><p>版本字段会变，课序钉的是机制对象「blkio cgroup」，不是某一主线内核的结构体名。 后课默认：cgroup 可节流块 I/O。如何要求设备掉电不丢这一笔，下一课屏障/FUA。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>io 控制器限制权重与上限；writeback 归属是关键。</li><li>与 FS 配额、精简池满不是同一层。</li><li>写屏障与 FUA 是下一课。</li><li>出处：cgroup v2 io；Linux blk-cgroup；Love 对 cgroup 的背景。</li></ul>',11))])}const B=l(u,[["render",b]]);export{E as __pageData,B as default};
